import { BalanceListener, FixedScaleVault } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function throwsType(fn: () => unknown, message: string): void {
  try { fn(); } catch (error) { assert(error instanceof TypeError, message); return; }
  throw new Error(`${message}: did not throw`);
}
function throwsRange(fn: () => unknown, message: string): void {
  try { fn(); } catch (error) { assert(error instanceof RangeError, message); return; }
  throw new Error(`${message}: did not throw`);
}

for (const bad of [-1, 19, 1.5, Number.MAX_SAFE_INTEGER + 1, Infinity, NaN]) {
  throwsRange(() => new FixedScaleVault(bad, 'TOK'), 'invalid decimals');
}
for (const bad of ['', ' ', '\t']) throwsType(() => new FixedScaleVault(2, bad), 'invalid symbol');

const vault = new FixedScaleVault(2, ' T ');
equal(vault.getSymbol(), ' T ', 'symbol preserved');
equal(vault.getDecimals(), 2, 'decimals returned');
equal(vault.parseAmount('0'), 0n, 'parse zero');
equal(vault.parseAmount('7'), 700n, 'parse integer');
equal(vault.parseAmount('7.1'), 710n, 'pad fraction');
equal(vault.parseAmount('7.10'), 710n, 'full fraction');
equal(vault.formatAmount(0n), '0.00', 'format zero');
equal(vault.formatAmount(710n), '7.10', 'format amount');
equal(vault.formatAmount(5n), '0.05', 'format subunit');

for (const bad of ['', '00', '01', '.1', '1.', '1.234', '-1', '+1', ' 1', '1 ', '1e2', '1_000']) {
  throwsRange(() => vault.parseAmount(bad), `malformed amount ${bad}`);
}
throwsType(() => vault.parseAmount(1 as unknown as string), 'non-string parse');
throwsType(() => vault.formatAmount(1 as unknown as bigint), 'non-bigint format');
throwsRange(() => vault.formatAmount(-1n), 'negative format');

const whole = new FixedScaleVault(0, 'UNIT');
equal(whole.parseAmount('12'), 12n, 'zero-decimal parse');
equal(whole.formatAmount(12n), '12', 'zero-decimal format');
throwsRange(() => whole.parseAmount('12.0'), 'dot forbidden at zero decimals');
const maxScale = new FixedScaleVault(18, 'MAX');
equal(maxScale.parseAmount('0.000000000000000001'), 1n, 'eighteen-decimal boundary');
equal(maxScale.formatAmount(1n), '0.000000000000000001', 'eighteen-decimal format');

const account = ' Alice ';
equal(vault.getBalance(account), 0n, 'unknown balance');
equal(vault.allowance(account, 'Bob'), 0n, 'unknown allowance');
vault.setBalance(account, 100n);
equal(vault.getBalance(account), 100n, 'set balance');
equal(vault.getBalance('Alice'), 0n, 'accounts preserve spaces');
vault.approve(account, 'Bob', 45n);
equal(vault.allowance(account, 'Bob'), 45n, 'approval stored');
equal(vault.allowance(account, 'bob'), 0n, 'accounts are case-sensitive');
for (const bad of ['', ' ', '\n']) {
  throwsType(() => vault.getBalance(bad), 'invalid balance account');
  throwsType(() => vault.allowance(account, bad), 'invalid spender');
}
throwsType(() => vault.setBalance(account, 1 as unknown as bigint), 'non-bigint balance');
throwsRange(() => vault.setBalance(account, -1n), 'negative balance');
throwsType(() => vault.approve(account, 'Bob', 1 as unknown as bigint), 'non-bigint allowance');
throwsRange(() => vault.approve(account, 'Bob', -1n), 'negative allowance');

const events: string[] = [];
let stopSecond = (): void => {};
const first: BalanceListener = (balance) => {
  events.push(`first:${balance.toString()}`);
  if (balance === 200n) stopSecond();
};
const second: BalanceListener = (balance) => { events.push(`second:${balance.toString()}`); };
const stopFirst = vault.subscribe(account, first);
stopSecond = vault.subscribe(account, second);
equal(events.join(','), 'first:100,second:100', 'immediate callbacks in subscription order');
events.length = 0;
vault.setBalance(account, 100n);
equal(events.length, 0, 'duplicate value emits nothing');
vault.setBalance(account, 200n);
equal(events.join(','), 'first:200,second:200', 'emission uses listener snapshot');
events.length = 0;
vault.setBalance(account, 300n);
equal(events.join(','), 'first:300', 'unsubscribe affects later emission');
stopFirst();
stopFirst();
events.length = 0;
vault.setBalance(account, 400n);
equal(events.length, 0, 'unsubscribe is idempotent');

const boom = new Error('listener failure');
const throwingListener: BalanceListener = () => { throw boom; };
let caught: unknown;
try { vault.subscribe('throwing', throwingListener); } catch (error) { caught = error; }
equal(caught, boom, 'immediate listener exception propagates');

